  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Approves a pending IPO application. It verifies that the application is in a pending state and that the related customer is still eligible to apply for IPO. Upon successful approval, the application status is changed to APPROVAL and two information emails are sent — one to the customer and another to the related company. The method returns true when the approval succeeds; otherwise, it returns false.
   * Algorithm:
   *   1. If this.status != PENDING, return false.
   *   2. If this.customer.isEligibleForIPO() == false, return false.
   *   3. Set this.status = APPROVAL.
   *   4. Create and add an information email addressed to the customer (receiver = customer.email) and another addressed to the company (receiver = company.email) to this.emails. The content of each email is produced via Email.createEmailContent(company, share, customer, amountOfMoney).
   *   5. Return true.
   * Related Features: status, customer, company, share, amountOfMoney, emails
   * Related Classes: Customer, Company, Email
   * Input: None
   * Output: boolean — true if the application was approved successfully; false otherwise.
   * Pre-condition: this.status == PENDING AND this.customer.isEligibleForIPO() == true.
   * Post-condition: this.status == APPROVAL AND this.emails contains two new Email objects (one for the customer and one for the company).
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean approve()
  {
    if (getStatus() != ApplicationStatus.PENDING)
    {
      return false;
    }
    Customer customer = getCustomer();
    if (customer == null || !customer.isEligibleForIPO())
    {
      return false;
    }
    setStatus(ApplicationStatus.APPROVAL);

    Company company = getCompany();
    Email customerEmail = IpoFactory.eINSTANCE.createEmail();
    String content = customerEmail.createEmailContent(company, getShare(), customer, getAmountOfMoney());
    customerEmail.setReceiver(customer.getEmail());
    customerEmail.setContent(content);
    getEmails().add(customerEmail);

    Email companyEmail = IpoFactory.eINSTANCE.createEmail();
    companyEmail.setReceiver(company.getEmail());
    companyEmail.setContent(content);
    getEmails().add(companyEmail);

    return true;
  }

